<script setup lang="ts">
import { computed,onBeforeUnmount,onMounted,ref,watch } from 'vue'
import { get,post } from '@/api/client'
import type { ModelFrame } from './products'
const parameter=ref('velocity'),allFrames=ref<ModelFrame[]>([]),run=ref(''),index=ref(0),playing=ref(false),ready=ref(false),error=ref(''),busy=ref(false)
const runs=computed(()=>[...new Set(allFrames.value.map(f=>f.run))].sort().reverse())
const frames=computed(()=>allFrames.value.filter(f=>f.run===run.value).sort((a,b)=>a.valid_at.localeCompare(b.valid_at)))
let generation=0,timer:ReturnType<typeof setInterval>|undefined,refresh:ReturnType<typeof setInterval>|undefined
const current=computed(()=>frames.value[index.value])
async function load(){const n=++generation;error.value='';try{const data=await get<{frames:ModelFrame[]}>('/sw/magnetosphere/frames',{parameter:parameter.value});if(n!==generation)return;allFrames.value=data.frames;if(!runs.value.includes(run.value))run.value=runs.value[0]||'';index.value=frames.value.reduce((best,f,i)=>Math.abs(Date.parse(f.valid_at)-Date.now())<Math.abs(Date.parse(frames.value[best]?.valid_at||'')-Date.now())?i:best,0);if(!data.frames.length)error.value='尚无缓存模型帧，请更新此信源。'}catch(e){if(n===generation)error.value=String(e)}}
async function sync(){busy.value=true;try{await post('/sw/sync',{source:'geospace_'+parameter.value});error.value='采集任务已启动，面板会自动检查结果。'}catch(e){error.value=String(e)}finally{busy.value=false}}
watch(parameter,()=>{playing.value=false;void load()});watch(current,()=>{ready.value=false})
watch(run,()=>{playing.value=false;index.value=0})
onMounted(()=>{void load();timer=setInterval(()=>{if(playing.value&&ready.value){if(index.value>=frames.value.length-1)playing.value=false;else index.value++}},600);refresh=setInterval(()=>{if(!playing.value)void load()},60000)})
onBeforeUnmount(()=>{generation++;clearInterval(timer);clearInterval(refresh)})
</script>
<template><section class="mhd-movie"><div class="mhd-image"><img v-if="current" :src="'/api/sw/assets?id='+current.id" alt="NOAA Geospace MHD模型的GSM赤道与子午面切片" @load="ready=true" @error="error='模型帧读取失败，可重试更新';ready=false"/><p v-else>等待 NOAA Geospace 模型产品</p></div><aside><b>太阳风—磁层相互作用</b><p>NOAA业务 Geospace/SWMF：BATS-R-US 磁流体模型、RIM 电离层模型、RCM 环电流模型。</p><p>保留原始色标与单位。图中可对照迎日面压缩、磁鞘和背日面磁尾。它是数值模型的二维切片，不是三维网格实测。</p><select v-model="parameter" aria-label="磁层模型变量"><option value="velocity">流速</option><option value="density">密度</option><option value="pressure">压力</option></select><select v-model="run" aria-label="磁层模型批次"><option v-for="batch in runs" :key="batch" :value="batch">{{batch}}</option></select><p>{{current?.valid_at}} · {{current&&Date.parse(current.valid_at)>Date.now()?"未来模型有效时刻":"模型有效时刻"}}</p><p>批次 {{current?.run||'未知'}}；不同批次明确保留。</p><button :disabled="!frames.length" @click="index=0;playing=true">从首帧播放</button><button @click="playing=!playing" :disabled="!frames.length">{{playing?'暂停':'继续'}}</button><input type="range" min="0" :max="Math.max(0,frames.length-1)" v-model.number="index" aria-label="磁层模型帧"/><p>{{frames.length?index+1:0}} / {{frames.length}}帧</p><button :disabled="busy" @click="sync">更新此信源</button><button @click="load">重新读取</button><p v-if="error" role="alert">{{error}}</p><a href="https://www.spaceweather.gov/products/geospace-magnetosphere-movies" target="_blank" rel="noreferrer">NOAA 模型依据、输入与限制 ↗</a></aside></section></template>
<style scoped>
button{background:#102737;color:#d1e7f2;border:1px solid #36576c;border-radius:4px;padding:6px 9px;cursor:pointer;font:11px 'Segoe UI','Microsoft YaHei',sans-serif}button:hover{border-color:#80bdcc;background:#173c50}button:disabled{opacity:.4;cursor:default}select{background:#102737;color:#d1e7f2;border:1px solid #36576c;padding:6px;font-size:11px}a{line-height:1.7}

.mhd-movie{position:absolute;inset:65px 0 0;background:#03090e;display:grid;grid-template-columns:minmax(0,1fr) 250px;z-index:6}.mhd-image{display:flex;align-items:center;justify-content:center;min-width:0;overflow:hidden}.mhd-image img{max-width:100%;max-height:100%;object-fit:contain}.mhd-movie aside{padding:15px;background:#0c1b28;overflow:auto;font-size:11px}.mhd-movie p{line-height:1.8;color:#a1b7ca;font-size:11px;overflow-wrap:anywhere}.mhd-movie select{width:100%}.mhd-movie input{width:100%;margin-top:15px}.mhd-movie a{color:#8bc5d9;font-size:10px}.mhd-movie button{margin:3px}@media(max-width:600px){.mhd-movie{inset:85px 0 0;grid-template-columns:1fr;grid-template-rows:1fr 190px}.mhd-movie aside{padding:10px}.mhd-movie aside>p:nth-of-type(1),.mhd-movie aside>p:nth-of-type(2){display:none}}
</style>
